    "feasibility": {
      "type": "number",
      "minimum": 1,
      "maximum": 10,
      "description": "How feasible is this idea (1-10)"
    },
    "resources": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Resources needed to implement"
    }
  },
  "required": [
    "idea",
    "category",
    "feasibility",
    "resources"
  ],
  "additionalProperties": false
}

